import sys

class Graph:
    def __init__(self, n):
        self.N = n
        self.nodes = [[] for _ in range(n)]
        self.is_edge = [False for _ in range(n)]

    def add_edge(self, u, v, w):
        u, v = min(u, v), max(u, v)
        if self.is_edge[v]:
            return 0
        self.nodes[u].append((v, w))
        self.nodes[v].append((u, w))
        self.is_edge[v] = True
        return 1

    def dfs(self, node, limit):
        for neighbor, weight in self.nodes[node]:
            if neighbor == limit:
                return weight
            cross_value = self.dfs(neighbor, limit)
            if cross_value  != 0:
                return weight + cross_value

    def was_init(self, u, v):
        weight = (self.N - u - v + 1) // 2 * (2 * u + 1)
        for neighbor, weight2 in self.nodes[u]:
            if neighbor == v:
                return True
            if (neighbor < u and neighbor < v) or (neighbor > v and neighbor > u) or (neighbor == u - v + 1):
                continue
            if (2 * neighbor + 1 < 2 * u + 1 and neighbor < v) or (2 * neighbor - u > v and 2 * neighbor - u < 2 * u + 1):
                continue
            if self.was_init(v, neighbor):
                break
        else:
            return False
