            x = int(command[1])
            y = int(command[2])
            a, c = cells.pop(x - 1)
            c -= y
            cells.insert(x - 1, (a, c))
        elif command[0] == '3':
            i = operations.index(['3'])
            if not cells: break
            x, cells_to_cover = min(set(range(a if a > k else k, a + 1) for a, c in cells) & current_cells)
