import sys

def longest_dokhtar_kosh_path(tree, weight, time, parent, level, memo):
    if level not in memo:
        max_path = 0
        subtree = 0
        for child in tree[level]:
            if child != parent:
                path_length, subtree_length = longest_dokhtar_kosh_path(tree, weight, time, child, level+1, memo)
                max_path = max(max_path, path_length)
                if subtree_length > 0:
                    max_path = max(max_path, subtree_length)
                subtree = max(subtree, path_length + 1, subtree_length + 1)
        memo[level] = (max_path, subtree)
    return memo[level]

