from collections import defaultdict

def generate_sequence(edges, components):
    max_length = max([len(x) for x in components])
    sequences = [0] * max_length
    for u, v, _ in edges:
        for i in range(len(components[u])):
            for j in range(1, max(components[u][i] - v + 1)):
                sequences[components[u][i] - v + 1] -= 1
                sequences[v + j] += 1
        for i in range(len(components[u])):
            for j in range(v, max(components[u][i] + 1)):
                sequences[j] += 1
    for i, count in enumerate(sequences):
        if count > 0:
            return sequences[:i], sequences[i:]
    return [-1]

def find_lexicographically_smallest_sequence(edges):
    graph = defaultdict(set)
    components = []

    def dfs(node, component):
        for neighbor in range(1, len(component) + 1):
            graph[0].add((0, neighbor))
        for neighbor in component:
            dfs(neighbor, operate(neighbor))

    def operate(x):
        components = [x]
        for _, y in graph[x]:
            dfs(y, components)
        return components

    dfs((0, [v - 1 for v in range(1, len(edges) + 1)]), components)

    if not components[0]:
        answer = []
        for node in range(len(edges) + 1):
            answer.append(-1)
        return answer

    used, unused = components.pop()

    while unused:
        _, unused = generate_sequence(edges, [used] * len(components) + unused)
        if unused:
            return answer

    for subchain in combinations(range(1, len(edges) + 1), len(components)):
        if subchain in graph[0]:
            _, unused = generate_sequence(edges, [subchain] * len(components) + unused)
            if unused:
                return answer
        else:
            _, unused = generate_sequence(edges, [subchain] * len(components) + unused)
            if unused:
                return answer

    return [-1]

