def find_minimal_sequence(t):
    for _ in range(t):
        N, M = map(int, input().split())
        graph = defaultdict(lambda: defaultdict(list))
        non_nodal_labels = set()
        for _ in range(M):
            x, y = map(int, input().split())
            non_nodal_labels.add(y)
            graph[0][y].append(x)

        possible_sequences = set()
        from collections import Counter

        def memo(f, x, depth, op):
            if (x, depth, op) in non_nodal_labels:
                return None
            if depth == N:
                return f(x)
            for nxt in graph[x][op]:
                res = None
                if nxt in non_nodal_labels:
                    res = memo(f, nxt, depth + 1, operation)
                if res:
                    possible_sequences.add(res)
                    return f(nxt)
            return None

        operations = [0] * (N + 1)
        operations[0] = 1
        for node, edges in sorted(graph[0].items(), key=lambda x: x[1]):
            for edge in edges:
                memo(operations, edge[0], 1, operations[edge[0]])

        non_zero_operations = set()
        for node, val in operations:
            if val:
                non_zero_operations.add(node)

        for node in non_zero_operations:
            if all(memo(graph, node[0], 0, x) for x in non_zero_operations):
                return " ".join(map(str, non_zero_operations))
        return "-1"

