def query1(arr, length, l, r, x):
    index = r - 1
    while index >= 0 and arr[index] > arr[index + 1] - x:
        arr[index] = arr[index] - x
        index -= 1
    if index < 0 or length[index + 1] - length[index] < l - 1:
        for i in range(1, r - l + 1):
            arr[index + 1 + i] = arr[index + i]
    else:
        arr[index + 1] = arr[index + 1] + 1
    index += 1
    while index < r:
        arr[index] = arr[index - 1]
        index += 1
    return arr, index, length

def query2(parent, u, v):
    if u == v:
        return u

    parent_v = parent[v]
    if parent_v == v:
        return v

    while parent_v != parent[u]:
        v = parent_v
        parent_v = parent[parent_v]

    while parent_v != parent[u]:
        u = parent[u]

    if v < u:
        return parent[u]
    return u

