import math
from functools import lru_cache

def calculate_gcd_max_power(N, nums):
    max_power = [0] * (N + 1)
    power_max = 0

    @lru_cache(maxsize=None)
    def max_power_of_subarray(subarray_start, subarray_size):
        nonlocal power_max
        current_power = nums[subarray_start]

        if subarray_size == 1:
            max_power[subarray_start] = current_power
            return current_power

        for i in range(subarray_start + 1, subarray_start + subarray_size + 1):
            current_power = math.gcd(current_power, nums[i])
            if current_power > power_max:
                power_max = current_power

        max_power[subarray_start] = power_max

    for start in range(N):
        for size in range(1, N + 1):
            max_power_of_subarray(start, size)

    return max_power

