                if i == 0 and nums[i] == len(nums) - 1 and nums[-1] != len(nums) - 1:
                    nums = nums[:i + 1] + [nums[i + 1] + nums[-1]] + nums[i + 2:-1]
                elif i == 0 and nums[i] == len(nums) - 1 and nums[-1] == len(nums) - 1:
                    nums = nums[:i + 1] + [nums[i + 1] + nums[-1]] + nums[i:]
